const h = $('Health').first().json;
const current = Object.fromEntries($('Current alerts').all().filter((i) => i.json.name).map((i) => [i.json.name, i.json]));
const now = new Date();
const rules = [
  { name: 'ai_failures', breached: h.ai_failed_1h >= 3, detail: `${h.ai_failed_1h} failed AI calls in the last hour`, runbook: 'runbooks/ai-gateway.md' },
  { name: 'invalid_output', breached: h.invalid_6h >= 3, detail: `${h.invalid_6h} invalid AI outputs in 6 hours`, runbook: 'runbooks/ai-gateway.md' },
  { name: 'budget_exceeded', breached: h.over_budget !== '', detail: `Daily AI budget reached: ${h.over_budget}`, runbook: 'runbooks/ai-gateway.md' },
  { name: 'reviews_overdue', breached: h.reviews_overdue > 0, detail: `${h.reviews_overdue} review(s) waiting more than 24h`, runbook: 'runbooks/review-backlog.md' },
  { name: 'run_failures', breached: h.runs_failed_1h >= 3, detail: `${h.runs_failed_1h} failed runs in the last hour`, runbook: 'runbooks/ai-gateway.md' },
  { name: 'workflow_errors', breached: h.errors_1h > 0, detail: `${h.errors_1h} workflow error(s) in the last hour`, runbook: 'Check the Error Handler emails' },
];
return rules.map((r) => {
  const prev = current[r.name] || { state: 'ok' };
  const wasFiring = prev.state === 'firing';
  const remind = r.breached && wasFiring && prev.last_notified && now - new Date(prev.last_notified) > 4 * 3600e3;
  const notify = r.breached !== wasFiring || remind;
  return {
    json: {
      name: r.name, state: r.breached ? 'firing' : 'ok', detail: r.detail, notify,
      subject: r.breached ? `● ${remind ? 'STILL FIRING' : 'ALERT'}: ${r.name}` : `✔ RESOLVED: ${r.name}`,
      body: `${r.detail}\n\nRunbook: ${r.runbook}\nTime: ${now.toISOString()}`,
    },
  };
});
